2	
3	import (
4		"bytes"
5		"encoding/json"
6		"net/http"
7		"net/http/httptest"
8		"path/filepath"
9		"testing"
10		"time"
11	
12		"github.com/luwa07832/service-discovery-api/internal/store"
13	)
14	
15	func testRouter(t *testing.T) (http.Handler, *store.Store) {
16		t.Helper()
17		st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
18		if err != nil {
19			t.Fatalf("open: %v", err)
20		}
21		t.Cleanup(func() { st.Close() })
22		return NewRouter(st), st
23	}
24	
25	func doRequest(t *testing.T, router http.Handler, method, target string, body any) *httptest.ResponseRecorder {
26		t.Helper()
27		var reader *bytes.Reader
28		if body != nil {
29			raw, err := json.Marshal(body)
30			if err != nil {
31				t.Fatalf("marshal: %v", err)
32			}
33			reader = bytes.NewReader(raw)
34		} else {
35			reader = bytes.NewReader(nil)
36		}
37		req := httptest.NewRequest(method, target, reader)
38		req.Header.Set("Content-Type", "application/json")
39		rec := httptest.NewRecorder()
40		router.ServeHTTP(rec, req)
41		return rec
42	}
43	
44	func registerInstance(t *testing.T, router http.Handler, body map[string]any) {
45		t.Helper()
46		rec := doRequest(t, router, http.MethodPost, "/api/v1/register", body)
47		if rec.Code != http.StatusOK {
48			t.Fatalf("register %v: status %d body %s", body, rec.Code, rec.Body.String())
49		}
50	}
51	
52	func decodeBody(t *testing.T, rec *httptest.ResponseRecorder) map[string]any {
53		t.Helper()
54		var out map[string]any
55		if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
56			t.Fatalf("decode %q: %v", rec.Body.String(), err)
57		}
58		return out
