525			t.Fatalf("get instance port = %v", instance["port"])
526		}
527	
528		out := decodeBody(t, doRequest(t, router, http.MethodGet,
529			"/api/v1/discover?service_name=svc&evaluate_at="+at(10)+"&heartbeat_timeout=5m", nil))
530		items := out["instances"].([]any)
531		first := items[0].(map[string]any)
532		second := items[1].(map[string]any)
533		if first["instance_id"] != "i-1" || first["port"].(float64) != 8080 {
534			t.Fatalf("discover first item = %v", first)
535		}
536		if second["instance_id"] != "i-2" || second["port"].(float64) != 0 {
537			t.Fatalf("discover default port = %v", second)
538		}
539	
540		// Invalid ports are rejected and change nothing.
541		rec = doRequest(t, router, http.MethodPost, "/api/v1/register", map[string]any{
542			"service_name": "svc", "instance_id": "i-3", "port": -1,
543			"weight": 1, "heartbeat_at": baseTime,
544		})
545		expectParameterError(t, rec)
546		if list, _ := st.ListInstances("svc"); len(list) != 2 {
547			t.Fatalf("invalid port changed storage: %d rows", len(list))
548		}
549	}
