551	func TestDiscoverBoundaryKeepsEqualAndEvictsStrictlyLater(t *testing.T) {
552		router, st := testRouter(t)
553		registerInstance(t, router, map[string]any{
554			"service_name": "svc", "instance_id": "edge", "healthy": true,
555			"weight": 1, "heartbeat_at": at(0),
556		})
557	
558		// Heartbeat exactly at heartbeat_at + timeout is still online.
559		target := "/api/v1/discover?service_name=svc&evaluate_at=" + at(10) + "&heartbeat_timeout=10m"
560		out := decodeBody(t, doRequest(t, router, http.MethodGet, target, nil))
561		if ids := instanceIDs(t, out); len(ids) != 1 || ids[0] != "edge" {
562			t.Fatalf("boundary ids = %v, want [edge]", ids)
563		}
564		if _, found, _ := st.GetInstance("svc", "edge"); !found {
565			t.Fatalf("boundary query deleted an online record")
566		}
567	
568		// One second past the boundary the instance is lost: excluded and deleted.
569		evaluate := time.Date(2026, 10, 1, 12, 10, 1, 0, time.UTC).Format(time.RFC3339)
570		target = "/api/v1/discover?service_name=svc&evaluate_at=" + evaluate + "&heartbeat_timeout=10m"
571		out = decodeBody(t, doRequest(t, router, http.MethodGet, target, nil))
572		if ids := instanceIDs(t, out); len(ids) != 0 {
573			t.Fatalf("past-boundary ids = %v, want []", ids)
574		}
575		if _, found, _ := st.GetInstance("svc", "edge"); found {
576			t.Fatalf("lost record was not deleted")
577		}
578	}
579	
580	func TestHeartbeatRestoresOnlyThatInstance(t *testing.T) {
581		router, st := testRouter(t)
582		registerInstance(t, router, map[string]any{
583			"service_name": "svc", "instance_id": "a", "healthy": true,
584			"weight": 5, "heartbeat_at": at(0),
585		})
586		registerInstance(t, router, map[string]any{
587			"service_name": "svc", "instance_id": "b", "healthy": true,
588			"weight": 8, "heartbeat_at": at(0),
589		})
590	
591		// A new heartbeat for one instance must not revive the other lost one.
592		registerInstance(t, router, map[string]any{
593			"service_name": "svc", "instance_id": "a", "healthy": true,
594			"weight": 5, "heartbeat_at": at(10),
595		})
596		peer, found, err := st.GetInstance("svc", "b")
597		if err != nil || !found {
598			t.Fatalf("peer record missing: found=%v err=%v", found, err)
599		}
600		wantHeartbeat, _ := time.Parse(time.RFC3339, at(0))
601		if !peer.HeartbeatAt.Equal(wantHeartbeat) {
602			t.Fatalf("heartbeat touched another instance: %+v", peer)
603		}
604	
605		out := decodeBody(t, doRequest(t, router, http.MethodGet,
606			"/api/v1/discover?service_name=svc&evaluate_at="+at(10)+"&heartbeat_timeout=1m", nil))
607		if ids := instanceIDs(t, out); len(ids) != 1 || ids[0] != "a" {
608			t.Fatalf("ids = %v, want [a]", ids)
609		}
610		if _, found, _ := st.GetInstance("svc", "b"); found {
611			t.Fatalf("lost peer was not cleaned up")
612		}
613	}
